import json
from pathlib import Path

root=Path(__file__).resolve().parents[1]
chapters={}
def steps(*rows):
    return [dict(title=r[0],gu=r[1],flow=r[2],target=r[3]) for r in rows]
def pathway(key,title,start,smi,conditions,product,psmi,theory,mechanism,why,stereo,trap,mode='pair'):
    return dict(id=key,title=title,starting=start,reactant=smi,conditions=conditions,product=product,productSmiles=psmi,theory=theory,steps=mechanism,why=why,stereo=stereo,trap=trap,flowMode=mode)
def chapter(id,intro,memory,compare,paths,qa,answer,distractors,ref='https://openstax.org/details/books/organic-chemistry'):
    chapters[id]=dict(id=id,level='slot3',intro=intro,memory=memory,comparison=compare,pathways=paths,conceptQuestion=qa,conceptAnswer=answer,conceptDistractors=distractors,referenceUrl=ref)

def cr_steps():
    return steps(('Chromate ester','Alcohol ના O lone pair, Cr(VI) સાથે bond બનાવે છે; proton transfer પછી chromate ester મળે છે.','Alcohol O lone pair','Electrophilic Cr(VI)'),('Align the carbinol C–H','જે carbon પર O છે તેના C–H bond અને O–Cr leaving unit યોગ્ય geometry મેળવે છે. Tertiary alcohol પાસે જરૂરી C–H નથી.','Carbinol C–H bond','Developing C=O system'),('Carbonyl-forming elimination','Base-assisted elimination માં C=O બને છે અને O–Cr bond તૂટે છે. Alcohol substrate oxidize અને chromium species reduce થાય છે.','C–H / O electron system','Carbonyl π bond'),('Read the medium','Dry medium માં aldehyde અલગ રહી શકે; water માં aldehyde hydrate બને તો બીજી oxidation acid આપે છે.','Aldehyde O lone pair','Water / acid equilibrium'))
def sulfoxide_steps(activator):
    return steps(('Activate DMSO',activator+' DMSO ને electrophilic sulfur reagent માં ફેરવે છે. માત્ર unactivated DMSO alcohol ને આ રીતે oxidize કરતું નથી.','DMSO oxygen lone pair','Activator'),('Bind the alcohol','Alcohol oxygen sulfur પર attack કરે છે. Proton transfer અને leaving-group departure થી alkoxysulfonium salt મળે છે.','Alcohol O lone pair','Activated sulfur'),('Generate the sulfur ylide','Base, sulfur-bound methyl group માંથી proton દૂર કરી sulfur ylide બનાવે છે; આ alcohol ના O–H ને માત્ર remove કરવાથી અલગ છે.','Base lone pair','Sulfur-methyl H'),('Eliminate to C=O','Cyclic proton-transfer/elimination sequence carbinol C–H દૂર કરે છે. Carbonyl compound અને dimethyl sulfide બને છે.','Ylide / carbinol C–H system','C=O + Me₂S'))
def iodine_steps():
    return steps(('Alcohol coordination','Alcohol oxygen, electrophilic iodine(V) સાથે ligand exchange કરે છે. Alkoxyiodinane intermediate બને છે.','Alcohol O lone pair','Iodine(V)'),('Proton transfer','Available carboxylate/basic oxygen alcohol-derived O–H proton દૂર કરવામાં મદદ કરે છે.','Basic oxygen lone pair','O–H proton'),('Arrange for elimination','Iodine-bound intermediate એવી geometry મેળવે છે કે carbinol C–H cleavage અને carbonyl formation શક્ય થાય.','Carbinol C–H system','Elimination alignment'),('Carbonyl release','C=O form થાય છે અને reduced iodine-containing products નીકળે છે. Primary alcohol aldehyde અને secondary alcohol ketone આપે છે.','C–H / alkoxy system','Carbonyl π bond'))
def hydride_steps(activation='Metal coordination carbonyl oxygen ને activate કરી શકે છે.'):
    return steps(('Identify the electrophile','C=O polarized છે: carbon electrophilic અને oxygen electron-rich છે. '+activation,'O lone pair','Lewis-acidic metal'),('Transfer hydride','Metal–H bond માંથી electron pair carbonyl carbon તરફ જાય છે; C=O π electrons oxygen પર જાય છે.','Metal–H bond','Carbonyl carbon'),('Recognize the alkoxide','નવું C–H bond અને metal-bound alkoxide બને છે. Ester/acyl derivative હોય તો leaving-group departure અને વધુ reduction તપાસો.','Former C=O π pair','Oxygen'),('Work-up releases alcohol','Protic work-up alkoxide oxygen ને proton આપે છે. Dry reaction stage અને aqueous work-up ને એકસાથે ન ગણી શકાય.','Alkoxide O lone pair','Work-up proton'))
def acyl_steps(nucleophile,leaving):
    return steps(('Nucleophilic attack',nucleophile+' carbonyl carbon પર attack કરે છે; C=O π electrons oxygen પર જાય છે.','Nucleophile lone pair','Acyl carbon'),('Tetrahedral intermediate','Carbonyl carbon થોડા સમય માટે tetrahedral થાય છે. Oxygen પર increased electron density/negative charge દેખાય છે.','C=O π electron pair','Oxygen'),('Collapse of intermediate','Oxygen lone pair C=O ફરી બનાવે છે અને '+leaving+' leaving group બહાર જાય છે.','Oxygen lone pair','Carbonyl π bond'),('Proton transfer','Acid–base steps neutral product બનાવે છે. Reaction medium મુજબ leaving fragment acid, carboxylate અથવા salt સ્વરૂપે રહે છે.','Base / product lone pair','Transferable proton'))
def p_oxid(id,name,conditions,kind):
    mech=cr_steps() if kind=='Cr' else iodine_steps() if kind=='I' else sulfoxide_steps('Oxalyl chloride' if id=='swern' else 'DCC / acid')
    return pathway(id+'-primary','Primary alcohol → aldehyde','Propan-1-ol','CCCO',conditions,'Propanal','CCC=O',name+' માં alcohol oxygen પહેલાં reagent સાથે interact કરે છે. પછી carbinol carbon પરથી બે hydrogen equivalents દૂર થાય છે; C–O connectivity જળવાઈને C=O બને છે. આ oxidation છે, dehydration નથી.',mech,'Aldehyde stop માટે water content અને reagent system મહત્વપૂર્ણ છે. Carbonyl carbon alcohol ના મૂળ OH-bearing carbon માંથી આવે છે.','No new stereocenter in this example. A chiral secondary-alcohol center would become planar on oxidation.','Dry oxidation rule ને aqueous strong oxidation પર લાગુ ન કરો.')
def p_secondary(id,name,conditions,mech):
    return pathway(id+'-secondary','Secondary alcohol → ketone','Cyclohexanol','OC1CCCCC1',conditions,'Cyclohexanone','O=C1CCCCC1','Secondary alcohol ના OH-bearing carbon પાસે એક C–H bond છે. '+name+' આ center ને ketone માં બદલે છે; ring ના C–C bonds આ normal transformation માં તૂટતા નથી.',mech,'C=O formation alcohol carbon ને trigonal planar બનાવે છે. Ordinary ketone hydrate formation primary aldehyde જેટલી આગળની oxidation માટે favorable નથી.','The original carbinol stereocenter is erased when it becomes planar C=O.','Tertiary alcohol પાસે carbinol H નથી; સામાન્ય alcohol-oxidation mechanism લાગુ પડતો નથી.')

chapter('pcc','PCC એક Cr(VI) oxidant છે. Dry conditions માં 1° alcohol ને aldehyde સુધી અને 2° alcohol ને ketone સુધી oxidize કરવો તેનો standard ઉપયોગ છે. Substrate oxygen chromate ester બનાવે છે; ત્યારબાદ elimination થાય છે.','PCC: Primary → Carbonyl, keep conditions dry.','Jones uses aqueous acid and normally carries a primary alcohol to the carboxylic acid.',[p_oxid('pcc','PCC','PCC, dry CH₂Cl₂','Cr'),p_secondary('pcc','PCC','PCC, dry solvent',cr_steps())],'What enables normal PCC oxidation of a secondary alcohol?','A C–H bond on the OH-bearing carbon',['An isolated alkene is compulsory','A tertiary alcohol is required','A free aryl radical is compulsory'],'https://openstax.org/books/organic-chemistry/pages/17-7-oxidation-of-alcohols')
jonesacid=pathway('jones-acid','Primary alcohol → carboxylic acid','Ethanol','CCO','CrO₃, aqueous H₂SO₄, acetone','Ethanoic acid','CC(=O)O','Jones conditions માં water હાજર હોવાથી શરૂઆતનું aldehyde hydrate સાથે equilibrium માં હોય છે. Gem-diol ફરી oxidize થઈ carboxylic acid આપે છે; aldehyde પર stop કરવાની સામાન્ય પદ્ધતિ આ નથી.',cr_steps(),'Water enables the aldehyde-to-gem-diol route. The second oxidation explains the acid endpoint.','No stereocenter is created in ethanol oxidation.','CrO₃/H₂SO₄/H₂O અને dry PCC ના endpoints એકસરખા ન લખો.')
chapter('jones','Jones reagent strongly acidic aqueous Cr(VI) oxidation system છે. Aldehyde hydrate formation primary-alcohol oxidation ને acid સુધી લઈ જાય છે; secondary alcohol ketone આપે છે.','Jones has water: aldehyde can go further.','PCC/Swern/DMP are standard aldehyde-stop alternatives for appropriate substrates.',[jonesacid,p_secondary('jones','Jones reagent','CrO₃ / H₂SO₄ / H₂O',cr_steps())],'Why does a primary alcohol normally give an acid under Jones conditions?','The initially formed aldehyde hydrates and is further oxidized',['The C–C chain must break','Jones reagent is a hydride donor','An alkyl radical is always the final intermediate'],'https://openstax.org/books/organic-chemistry/pages/17-7-oxidation-of-alcohols')
for id,name,cond,activation in [('swern','Swern oxidation','1. DMSO, (COCl)₂, low temperature; 2. Et₃N','Oxalyl chloride'),('moffatt','Pfitzner–Moffatt oxidation','DMSO, DCC, catalytic acid','DCC / acid')]:
    chapter(id,name+' માં activated DMSO alcohol oxygen સાથે alkoxysulfonium intermediate બનાવે છે. Base-driven ylide/elimination sequence carbonyl આપે છે. Oxidation દરમિયાન substrate oxygen product માં જ રહે છે.','Activate sulfur → bind alcohol → ylide → carbonyl.','Swern activates DMSO with oxalyl chloride; Moffatt uses a carbodiimide such as DCC.',[p_oxid(id,name,cond,'S')],'Which reagent activates DMSO in this oxidation?',activation,['OsO₄','NaBH₄','A Grignard reagent'],'https://archive.nptel.ac.in/content/storage2/courses/104103023/module1/lec3/2.html')
chapter('dmp','Dess–Martin periodinane iodine(V) oxidant છે. Alcohol ligand exchange અને elimination દ્વારા carbonyl આપે છે. Primary alcohol માટે aldehyde endpoint અને relatively mild medium synthetic planning માં ઉપયોગી છે.','DMP: exchange at I(V), eliminate to C=O.','mCPBA is a peracid used for alkene epoxidation/Baeyer–Villiger oxidation; it is not a substitute for every DMP transformation.',[p_oxid('dmp','DMP','DMP, CH₂Cl₂','I'),p_secondary('dmp','DMP','DMP, mild conditions',iodine_steps())],'What is the usual oxidation state of iodine in DMP?','+5',['−1','0','+1'])
chapter('ibx','IBX એટલે 2-iodoxybenzoic acid, iodine(V) oxidant. Alcohol–iodine ligand exchange અને suitable geometry પછી elimination થાય છે. IBX ની solubility DMP કરતાં અલગ હોવાથી solvent selection ખરેખર અસર કરે છે.','IBX and DMP share I(V); their solubility and conditions differ.','Do not infer identical conditions merely because two reagents both contain iodine(V).',[p_oxid('ibx','IBX','IBX, commonly DMSO','I')],'Which statement about IBX is correct?','It is an iodine(V) oxidant commonly used for alcohol oxidation',['It is a soft methyl-transfer cuprate','It is identical to NaBH₄','It always epoxidizes isolated alkenes preferentially'])

epox=pathway('mcpba-epoxide','Alkene → epoxide','Propene','CC=C','mCPBA; suitable solvent / buffer','Propylene oxide','CC1CO1','Electron-rich alkene અને peracid વચ્ચે concerted oxygen transfer થાય છે. O–O bond તૂટે છે અને એક જ overall event માં બે C–O bonds બને છે. Free carbon carbocation જરૂરી નથી.',steps(('Approach the π bond','Peracid terminal electrophilic oxygen alkene face પાસે આવે છે.','Alkene π pair','Peracid terminal O'),('Concerted bond reorganization','C–O bonds બનવા સાથે O–O cleavage અને proton transfer coupled હોય છે.','O–O / π electron system','New C–O bonds'),('Release epoxide','Three-membered epoxide ring અને carboxylic acid byproduct મળે છે.','Concerted electron reorganization','Epoxide connectivity'),('Inspect the stereochemistry','Alkene પર રહેલી relative substituent geometry stereospecifically preserve થાય છે; achiral faces બંને react કરી શકે.','Starting alkene geometry','Epoxide relative stereochemistry')),'The concerted mechanism retains the alkene’s relative geometry. Acid-sensitive epoxides may need buffering.','Stereospecific; achiral propene gives racemic propylene oxide.','An electron-poor enone may favor nucleophilic peroxide epoxidation instead.')
bv=pathway('mcpba-bv','Ketone → ester / lactone','Cyclohexanone','O=C1CCCCC1','mCPBA','ε-Caprolactone','O=C1CCCCCO1','Peracid carbonyl પર addition કરીને Criegee intermediate બનાવે છે. પછી adjacent group oxygen તરફ migrate થાય છે અને O–O bond તૂટે છે; cyclic ketone માં ring માં oxygen insert થાય છે.',steps(('Carbonyl addition','Peracid oxygen activated carbonyl carbon પર attack કરે છે.','Peracid O lone pair','Carbonyl carbon'),('Criegee intermediate','Tetrahedral peroxide intermediate migration માટે arrange થાય છે.','Carbonyl π pair','Oxygen'),('Migration with O–O cleavage','Migrating C–C bond oxygen તરફ જાય છે અને peroxide bond cleaves.','Migrating C–C bond','Adjacent peroxide oxygen'),('Ester release','Proton transfer પછી lactone મળે છે; ring એક oxygen atom થી expand થાય છે.','Oxonium O–H system','Neutral ester')),'Migration requires both migratory ability and stereoelectronic alignment; the symmetric ketone avoids a regioisomer question.','Configuration at a migrating stereogenic carbon is retained.','Baeyer–Villiger inserts O adjacent to C=O; it does not simply reduce C=O to alcohol.')
chapter('mcpba','mCPBA peracid છે. Substrate alkene હોય તો epoxide, ketone હોય તો Baeyer–Villiger ester/lactone મળવાની શક્યતા હોય છે. Substrate class બદલતાં mechanism પણ બદલાય છે.','C=C gets an O bridge; ketone gets O insertion.','Electrophilic peracid epoxidation and nucleophilic H₂O₂/base epoxidation of enones have different substrate preferences.',[epox,bv],'Which intermediate belongs to Baeyer–Villiger oxidation?','Criegee intermediate',['A sulfur ylide','A Grignard alkoxide','An aryl diazonium ion'])
oso=pathway('os-syn','Alkene → vicinal syn-diol','Ethene','C=C','1. OsO₄; 2. hydrolysis; catalytic variants use a co-oxidant','Ethane-1,2-diol','OCCO','OsO₄ alkene સાથે cyclic osmate ester બનાવે છે. બંને oxygen atoms એક face પરથી add થતા હોવાથી syn relationship બને છે. Hydrolysis diol release કરે છે.',steps(('Cyclic addition','Alkene અને OsO₄ વચ્ચે cyclic bond reorganization થી osmate ester બને છે.','Alkene π system','Electrophilic Os–O system'),('Same-face C–O bonds','બંને C–O bonds cyclic intermediate દ્વારા એક face પર install થાય છે.','Osmium-bound oxygens','Adjacent alkene carbons'),('Hydrolyze the ester','Hydrolysis organic O–Os links તોડી diol release કરે છે.','Water / O–Os system','Diol O–H groups'),('Regenerate catalyst when used','Catalytic protocols માં NMO જેવા co-oxidant reduced osmium ને reoxidize કરે છે.','Reduced osmium','Oxidant-mediated regeneration')),'A cyclic intermediate links the two oxygen deliveries and gives syn addition.','Ethene has no stereocenters. For substituted alkenes, use geometry and symmetry before calling the product meso.','Syn is a relative addition mode, not a universal synonym for meso.')
chapter('oso4','Osmium tetroxide vicinal syn-dihydroxylation માટે છે. Cyclic osmate ester ની hydrolysis diol આપે છે; catalytic OsO₄ માટે terminal co-oxidant પણ જોઈએ.','One face, two oxygens: syn diol.','Peracid epoxidation gives an epoxide; OsO₄/hydrolysis gives a diol.',[oso],'What controls syn dihydroxylation with OsO₄?','Formation of a cyclic osmate ester',['A free planar alkyl carbocation','Two unrelated random oxygen attacks','Anti attack by a bromide ion'])
seo=pathway('se-allylic','Allylic C–H oxidation','Cyclohexene','C1=CCCCC1','SeO₂; appropriate solvent / oxidant system','Cyclohex-2-en-1-ol','OC1C=CCCC1','SeO₂ allylic C–H bond પર oxidation કરી શકે છે. Standard mechanistic picture માં ene-type step, rearrangement અને hydrolysis આવે છે; simple example માં alkene retain થાય છે.',steps(('Find the allylic H','C=C ની બાજુના saturated carbon પર H જરૂરી છે; vinylic H અલગ છે.','Alkene / allylic C–H system','Electrophilic selenium'),('Ene-type step','Concerted bond reorganization allylic selenium-containing intermediate બનાવે છે.','Alkene π electron system','Selenium-bound intermediate'),('Rearrangement','Selenium-containing intermediate rearrange થઈ oxygenated allylic framework આપે છે.','Allylic bond system','Rearranged oxygenated center'),('Hydrolysis','Hydrolysis allylic alcohol release કરે છે. Further oxidation can occur for some substrates.','Hydrolytic O–Se cleavage','Allylic alcohol')),'Allylic stabilization and suitable C–H geometry make allylic positions reactive.','Regioisomer mixtures are possible when nonequivalent allylic sites compete.','SeO₂ does not universally cleave C=C like ozonolysis.')
chapter('seo2','Selenium dioxide allylic oxidation માટે classic reagent છે. Product અને site substrate, temperature અને oxidation extent પર આધાર રાખે છે; એક universal allylic-product rule નથી.','SeO₂ looks beside the double bond.','O₃ cleaves C=C; SeO₂ commonly oxygenates an allylic position.',[seo],'Which carbon is allylic?','An sp³ carbon directly adjacent to a C=C bond',['A carbon directly in the C=C bond','Any aromatic ipso carbon','Only the carbonyl carbon'])
def ozone_path(oxidative=False):
    return pathway('ozone-'+('oxidative' if oxidative else 'reductive'),'Oxidative cleavage → acids' if oxidative else 'Reductive cleavage → carbonyls','But-2-ene' if oxidative else 'Propene','CC=CC' if oxidative else 'CC=C','1. O₃; 2. H₂O₂' if oxidative else '1. O₃; 2. Me₂S or Zn/AcOH','Two ethanoic-acid fragments' if oxidative else 'Ethanal + methanal','CC(=O)O.CC(=O)O' if oxidative else 'CC=O.C=O','Ozone alkene ને cleave કરે છે. પહેલા primary ozonide, પછી carbonyl oxide / carbonyl recombination અને ozonide pathway આવે છે. Work-up oxidation state નક્કી કરે છે.',steps(('Cycloaddition','Alkene અને ozone 1,3-dipolar cycloaddition કરીને primary ozonide બનાવે છે.','Alkene π electrons','Ozone dipolar system'),('Fragment and recombine','Primary ozonide carbonyl oxide અને carbonyl species માં fragment થઈ secondary ozonide pathway આપે છે.','Ozonide bond system','Carbonyl oxide / carbonyl'),('Destroy peroxide links','Work-up peroxide bonds process કરે છે; oxidative work-up aldehydes ને આગળ acid સુધી લઈ જઈ શકે.','Peroxide bond system','Work-up-dependent products'),('Count both carbon fragments','Original C=C ના બંને carbons પોતાના attached groups સાથે carbonyl-derived products આપે છે.','Original C=C carbon positions','Two product fragments')),'Reductive work-up preserves aldehydes; an oxidative work-up may further oxidize aldehyde-derived fragments.','Original alkene E/Z information is lost when the bond is cleaved.','Terminal CH₂ gives a one-carbon fragment; do not omit it. Strong oxidative conditions can oxidize one-carbon products further.')
chapter('ozone','Ozonolysis product prediction માટે C=C mentally cut કરો, પછી દરેક carbon પર O મૂકો અને work-up વાંચો. Ozone addition અને reductive/oxidative work-up બે અલગ stages છે.','Cut C=C; cap both carbons with O; check work-up.','Me₂S or Zn/AcOH preserves aldehydes; peroxide work-up can give acids.',[ozone_path(),ozone_path(True)],'What must be specified to predict ozonolysis products?','The work-up after ozone addition',['Only the solvent color','Only whether the reagent bottle is solid','The molecular formula alone'])

lahester=pathway('lah-ester','Ester → alcohol fragments','Ethyl benzoate','CCOC(=O)c1ccccc1','LiAlH₄, dry ether/THF; then controlled work-up','Benzyl alcohol + ethanol','OCc1ccccc1.CCO','Ester carbonyl પર hydride addition પછી tetrahedral intermediate collapse થઈ aldehyde મળે છે. Aldehyde ester કરતાં વધુ reactive હોવાથી બીજો hydride તેને alkoxide સુધી reduce કરે છે.',hydride_steps(),'An aldehyde intermediate cannot normally be isolated with excess LiAlH₄ because it is rapidly reduced. The alkoxy fragment becomes its alcohol on work-up.','Achiral example; carbonyl-face selection matters for prochiral ketones.','An ester usually consumes two hydride transfers at the acyl carbon; do not stop at aldehyde.')
lahamide=pathway('lah-amide','Amide → amine','Benzamide','NC(=O)c1ccccc1','LiAlH₄; then work-up','Benzylamine','NCc1ccccc1','Amide reduction માં carbonyl oxygen દૂર થાય છે પણ carbonyl carbon carbon chain માં જ રહે છે. Oxygen–aluminium affinity અને hydride transfers iminium-like intermediate ને amine માં બદલે છે.',steps(('Coordinate oxygen','Amide oxygen aluminium સાથે coordinate કરે છે; N–H હોય તો acid–base consumption પણ થઈ શકે.','Amide O lone pair','Aluminium'),('Hydride addition','Hydride carbonyl carbon પર add થઈ tetrahedral aluminate બનાવે છે.','Al–H bond','Carbonyl carbon'),('Oxygen removal','Aluminium-bound oxygen-containing group loss થી iminium-like species મળે છે.','N lone pair / C–O system','C=N-derived intermediate'),('Further reduction','Hydride iminium carbon પર add થાય છે અને work-up amine release કરે છે.','Al–H bond','Iminium carbon')),'Strong Al–O bonding helps remove the oxygen-containing group. The carbon skeleton is preserved.','No stereocenter in benzylamine.','Hofmann rearrangement loses one carbon; LiAlH₄ reduction retains it.')
chapter('lialh4','LiAlH₄ strong hydride donor છે: aldehydes, ketones, esters, acids અને amides પર અલગ endpoints આવે છે. Free protic groups hydride consume કરે છે, એટલે substrate compatibility તપાસવી જરૂરી છે.','Strong hydride: ester to alcohol; amide to amine.','NaBH₄ is milder; DIBAL-H can stop selected ester reductions at an aldehyde under controlled conditions.',[lahester,lahamide],'What happens to the carbonyl carbon when an amide is reduced with LiAlH₄?','It remains in the amine carbon skeleton',['It is always expelled as CO₂','It becomes nitrogen','It is replaced by a chlorine atom'])
nbket=pathway('nb-ketone','Ketone → secondary alcohol','Propanone','CC(C)=O','NaBH₄, alcoholic solvent; work-up','Propan-2-ol','CC(O)C','NaBH₄ aldehyde અને ketone માટે mild hydride reagent છે. Hydride carbonyl carbon પર attack કરે છે, π electrons O પર જાય છે, પછી protonation થી alcohol મળે છે.',hydride_steps('Solvent and metal coordination alter reaction rate and selectivity.'),'A polar C=O bond is susceptible to nucleophilic hydride addition; an ordinary isolated C=C is not normally reduced.','Achiral acetone gives achiral 2-propanol; an unsymmetrical prochiral ketone normally gives a racemate without a chiral influence.','Ordinary alcoholic NaBH₄ does not generally reduce unactivated esters.')
nbselect=pathway('nb-selective','Ketone reduction with ester retained','Ethyl 4-oxocyclohexanecarboxylate','CCOC(=O)C1CCC(=O)CC1','NaBH₄, MeOH; work-up','Ethyl 4-hydroxycyclohexanecarboxylate','CCOC(=O)C1CCC(O)CC1','એક molecule માં ketone અને ester બંને હોય તો ordinary NaBH₄ conditions ketone ને preferentially reduce કરી શકે છે. Resonance-stabilized ester carbonyl comparatively less reactive છે.',hydride_steps(),'The ketone is more electrophilic toward mild borohydride than the ester under these standard conditions.','Cis/trans alcohol isomers can form; the drawing does not assign a single diastereomer.','Specially activated or modified borohydride systems may behave differently from ordinary NaBH₄.')
chapter('nabh4','NaBH₄ aldehyde/ketone reduction માટે mild hydride source છે. Chemoselectivity ને reagent નામ સાથે solvent, additives અને substrate activation પણ બદલાવે છે.','NaBH₄ usually selects aldehyde / ketone over ester.','LiAlH₄ broadly reduces ester groups; Luche adds Ce(III) to improve enone 1,2 reduction.',[nbket,nbselect],'Which group normally survives ordinary alcoholic NaBH₄ conditions?','An unactivated ester',['An aldehyde','An ordinary ketone','Every iminium ion'])
dibal_steps=steps(('Coordinate the acyl oxygen','Lewis-acidic Al carbonyl oxygen સાથે coordinate કરે છે.','Carbonyl O lone pair','Aluminium'),('Controlled hydride transfer','Hydride acyl carbon પર add થઈ tetrahedral aluminium-bound intermediate આપે છે.','Al–H bond','Ester / nitrile carbon'),('Limit further reaction','Low temperature, equivalents અને mixing intermediate fate નક્કી કરે છે; reagent name alone endpoint guarantee નથી.','Bound intermediate','Controlled reaction endpoint'),('Hydrolyze','Hydrolysis ester-derived intermediate અથવા nitrile-derived imine species માંથી aldehyde આપે છે.','Water / bound heteroatom','Aldehyde release'))
chapter('dibal','DIBAL-H bulky, Lewis-acidic hydride reagent છે. Controlled partial reduction થી selected esters અથવા nitriles aldehyde આપી શકે છે. More hydride/warming over-reduction વધારી શકે છે.','DIBAL: control equivalents, temperature and work-up.','LiAlH₄ usually carries an ester through to a primary alcohol.',[pathway('dibal-ester','Ester → aldehyde','Methyl benzoate','COC(=O)c1ccccc1','Controlled DIBAL-H, low temperature; hydrolysis','Benzaldehyde','O=Cc1ccccc1','Ester oxygen coordination પછી one hydride transfer થાય છે. Aluminium-bound intermediate controlled conditions માં રહે તો hydrolysis પછી aldehyde મળે છે.',dibal_steps,'A bound tetrahedral intermediate and controlled reagent exposure permit partial reduction.','No new stereocenter in benzaldehyde.','−78 °C alone does not guarantee selectivity in a multifunctional substrate.'),pathway('dibal-nitrile','Nitrile → aldehyde','Benzonitrile','N#Cc1ccccc1','DIBAL-H; then aqueous hydrolysis','Benzaldehyde','O=Cc1ccccc1','Hydride nitrile carbon પર add થાય છે. Aluminium-bound imine-derived intermediate ની hydrolysis carbonyl આપે છે.',dibal_steps,'Hydrolysis converts the C=N-derived intermediate to C=O.','Aldehyde carbon is planar.','Do not report a primary amine: that is the common LiAlH₄ nitrile-reduction endpoint.')],'What releases the aldehyde from a DIBAL nitrile reduction intermediate?','Hydrolysis of an imine-derived intermediate',['A Suzuki coupling','A radical bromination','An aromatic nitration'])
chapter('luche','Luche reduction માં NaBH₄ સાથે CeCl₃·7H₂O વપરાય છે. Ce(III) coordination conjugated ketone ના carbonyl reduction ને favor કરે છે, જેથી allylic alcohol મળે છે.','Luche: reduce C=O, retain C=C.','A cuprate adds carbon at the β position; Luche supplies hydride at the carbonyl carbon.',[pathway('luche-enone','Enone → allylic alcohol','Cyclohex-2-en-1-one','O=C1C=CCCC1','NaBH₄, CeCl₃·7H₂O, MeOH; work-up','Cyclohex-2-en-1-ol','OC1C=CCCC1','Enone પાસે carbonyl carbon અને β-carbon એમ બે electrophilic regions છે. Ce(III)-modified borohydride system carbonyl 1,2-reduction ને favor કરે છે.',hydride_steps('Ce(III) coordination modifies carbonyl activation and the reducing system.'),'The Lewis-acid additive changes the competition between direct and conjugate reduction.','Achiral starting material/reagents give racemic allylic alcohol in this example.','The standard product retains the alkene; do not draw a saturated ketone.')],'What is the hallmark of a standard Luche reduction?','1,2-reduction of an enone to an allylic alcohol',['1,4 methyl addition','Alkene oxidative cleavage','Carboxylic-acid decarboxylation'],'https://doi.org/10.1021/ja00475a040')
birch=pathway('birch-anisole','Arene → nonconjugated 1,4-diene','Anisole','COc1ccccc1','Li or Na, liquid NH₃, alcohol proton source','1-Methoxycyclohexa-1,4-diene','COC1=CCC=CC1','Birch reduction aromatic π system માં sequential single-electron અને proton transfers કરે છે. Two hydrogens ઉમેરાય છે અને aromatic ring nonconjugated diene બને છે.',steps(('First electron','Metal arene π* system માં એક electron આપે છે; radical anion બને છે.','Metal electron','Arene π* orbital'),('First proton','Radical-anion intermediate proton source પરથી H લે છે; regiochemistry substituents થી પ્રભાવિત થાય છે.','Radical-anion electron density','Proton source H'),('Second electron','Second electron transfer cyclohexadienyl anion-derived intermediate આપે છે.','Metal electron','Carbon-radical center'),('Second proton','Protonation nonconjugated 1,4-diene બનાવે છે. Anisole માં methoxy-bearing carbon સામાન્ય textbook product માં sp² રહે છે.','Anionic carbon pair','Proton source H')),'Electron-donating and electron-withdrawing substituents influence protonation sites differently.','Regioselective partial reduction; multiple substituted substrates need individual analysis.','The product is a 1,4-diene, not cyclohexane and not the usual conjugated 1,3-diene.','radical')
chapter('birch','Birch reduction arene ને 1,4-cyclohexadiene framework માં partially reduce કરે છે. Electron metalમાંથી અને protons proton donorમાંથી આવે છે; NH₃ મુખ્યત્વે solvent છે.','Electron → proton → electron → proton.','Dissolving-metal alkyne reduction gives an alkene; Birch refers to partial arene reduction.',[birch],'What is the characteristic Birch product class?','A nonconjugated 1,4-cyclohexadiene',['An aromatic nitrile','A fully saturated ring in every case','A carboxylic anhydride'])
wilkinson=pathway('rh-hydrogenation','Alkene → alkane','Propene','CC=C','H₂, RhCl(PPh₃)₃','Propane','CCC','Wilkinson catalyst homogeneous Rh system છે. Ligand loss, H₂ oxidative addition, alkene insertion અને reductive elimination catalytic sequence બનાવે છે; exact coordination order equilibria પર આધાર રાખી શકે છે.',steps(('Ligand dissociation','PPh₃ loss coordination site ખોલે છે. Rh(I) precatalyst d⁸, 16-electron છે.','Rh–P coordination','Open Rh site'),('H₂ activation','Oxidative addition H–H bond ને metal-bound hydrides માં ફેરવે છે; Rh oxidation state formally વધે છે.','H–H bond','Rh hydride complex'),('Alkene insertion','Coordinated alkene Rh–H bond માં insert થાય છે અને metal–alkyl intermediate મળે છે.','Coordinated alkene / Rh–H','Rh–alkyl intermediate'),('Product release','Reductive elimination alkane release કરીને low-valent catalyst regenerate કરે છે.','Rh–C and Rh–H bonds','New C–H bond')),'Ligand-controlled coordination and insertion determine rate and substrate preference.','Hydrogen delivery occurs through coordinated intermediates; no stereocenter in propane.','Grubbs is Ru metathesis; Wilkinson is Rh hydrogenation.','cycle')
chapter('wilkinson','RhCl(PPh₃)₃ homogeneous alkene hydrogenation catalyst છે. Catalyst અને H₂ ના roles અલગ છે: Rh reaction pathway આપે છે, H₂ hydrogen source છે.','Rh + H₂: hydrogenation; Ru alkylidene: metathesis.','A catalyst changes reaction rate and pathway; it is regenerated rather than supplying unlimited hydrogen.',[wilkinson],'What is the metal in Wilkinson’s catalyst?','Rhodium',['Ruthenium','Palladium','Copper'])
clem=pathway('clemmensen-carbonyl','Carbonyl → methylene in acid','Acetophenone','CC(=O)c1ccccc1','Zn(Hg), strongly acidic aqueous HCl','Ethylbenzene','CCc1ccccc1','Clemmensen carbonyl deoxygenation metal surface પર strongly acidic conditions માં થાય છે. Mechanism complex અને substrate-dependent છે; નીચે formal teaching stages છે, universally established elementary sequence નથી.',steps(('Check acid compatibility','Acid-sensitive groups હોય તો alternative deoxygenation strategy વિચારવી પડે છે.','Substrate functionality','Acid-compatible pathway'),('Metal-surface interaction','Carbonyl-containing substrate zinc surface સાથે interact કરે છે; protonation/adsorption coupled થઈ શકે છે.','Carbonyl / metal interface','Surface-bound species'),('Net reduction','Multiple electron/proton transfers અને oxygen removal formal C=O → CH₂ conversion આપે છે.','Metal-derived electrons','Carbonyl-derived carbon'),('Read the endpoint','Carbonyl carbon carbon skeleton માં જ રહે છે; ketone oxygen product માં રહેતું નથી.','Original carbonyl carbon','Methylene carbon')),'The observed strongly acidic metal-surface reduction is reliable as a named transformation; detailed universal arrows should not be invented.','No stereocenter is formed in ethylbenzene.','Do not assign hydrazone/N₂-loss steps to Clemmensen; those belong to Wolff–Kishner.','net')
chapter('clemmensen','Clemmensen aldehyde/ketone ને methylene સુધી reduce કરે છે. Strong acid અને metal surface તેની defining features છે; acid-labile substrates માટે તે હંમેશા યોગ્ય નથી.','Clemmensen = acidic metal reduction.','Wolff–Kishner uses hydrazine, strong base and heat.',[clem],'Which condition characterizes Clemmensen reduction?','Zn(Hg) in strongly acidic medium',['NH₂NH₂/KOH','NaBH₄/CeCl₃','mCPBA'])
wk=pathway('wk-hydrazone','Carbonyl → methylene via hydrazone','Acetophenone','CC(=O)c1ccccc1','NH₂NH₂, KOH, heat','Ethylbenzene','CCc1ccccc1','Hydrazine carbonyl સાથે condensation કરી hydrazone બનાવે છે. Strong-base proton transfers પછી N₂ loss થાય છે; resulting carbon anion protonate થઈ methylene product આપે છે.',steps(('Make the hydrazone','Hydrazine N lone pair C=O પર attack કરે છે; dehydration પછી C=N–NH₂ hydrazone મળે છે.','Hydrazine N lone pair','Carbonyl carbon'),('Base and proton transfers','N deprotonation અને carbon protonation/reorganization diazene-type intermediate તરફ લઈ જાય છે.','Base lone pair','Hydrazone N–H'),('Lose nitrogen','Further deprotonation પછી N₂ extrusion carbon-centered anionic character ઉત્પન્ન કરે છે.','C–N / N–N electron system','N₂ + carbon anion'),('Protonate carbon','Carbon anion proton source પરથી H લઈ reduced hydrocarbon આપે છે.','Carbon lone pair','Proton source H')),'Formation of very stable N₂ provides an important driving force.','A planar carbon-centered intermediate can erase stereochemical information at the reaction site.','Strong base/heat can damage base-sensitive functionality; do not choose only by the carbonyl group.')
chapter('wolff','Wolff–Kishner carbonyl deoxygenation hydrazone chemistry દ્વારા થાય છે. Stable nitrogen gas formation અને base-driven steps તેને Clemmensen થી mechanistically અલગ બનાવે છે.','Hydrazone → base → N₂ out → CH₂.','Clemmensen is acidic; Wolff–Kishner is strongly basic and heated.',[wk],'Which gaseous product helps drive Wolff–Kishner reduction?','N₂',['O₂','Cl₂','CO'])
lindlar=pathway('lindlar-z','Internal alkyne → Z-alkene','But-2-yne','CC#CC','H₂, poisoned Pd/CaCO₃ catalyst','(Z)-But-2-ene',r'C/C=C\C','Poisoned Pd catalyst alkyne ને partially hydrogenate કરે છે. Surface-bound delivery બંને hydrogens એક face પર add કરવાથી suitable internal alkyne Z-alkene આપે છે.',steps(('Adsorb alkyne','Alkyne catalyst surface સાથે bind થાય છે; H₂ surface પર activate થાય છે.','Alkyne / catalyst surface','Adsorbed alkyne'),('Same-face delivery','Surface geometry hydrogen atoms ને same face થી deliver કરે છે.','Surface-bound H atoms','Alkyne carbons'),('Release alkene','Poisoning alkene ની વધુ hydrogenation suppress કરે છે અને alkene release થાય છે.','Catalyst-bound alkene','Solution alkene'),('Assign Z only when possible','Internal alkene માં higher-priority groups same side હોય તો Z છે; terminal alkene માં E/Z લાગુ પડતું નથી.','Substituent priorities','Z / E assignment')),'Catalyst poisoning reduces the tendency to continue hydrogenation to alkane.','Syn partial hydrogenation gives Z for the symmetric internal-alkyne example.','Na/Li in liquid NH₃ gives the trans/E counterpart under standard dissolving-metal conditions.','net')
